inserted AS (
  INSERT INTO direct_catalog_services (
    category_id, slug, name_i18n, description_i18n, price_cents, currency_code,
    availability_days, available_days, sort_order, display_order, is_active,
    is_published, lifecycle_status, is_operationally_available, is_bookable,
    is_featured, published_at
  )
  SELECT c.id, s.slug, s.name_i18n, s.description_i18n, s.price_cents,
    s.currency_code, s.availability_days, s.available_days, s.sort_order,
    s.display_order, TRUE, TRUE, 'live', TRUE, FALSE, FALSE, CURRENT_TIMESTAMP
  FROM seeded s
  JOIN direct_catalog_categories c ON c.slug = s.category_slug
  ON CONFLICT (slug) DO NOTHING
  RETURNING id, slug
)
INSERT INTO catalog_status_history (item_type, item_id, from_status, to_status, changed_by, reason)
SELECT 'service', inserted.id, NULL, 'live', NULL, 'Published 1,000-service Direct catalog expansion'
FROM inserted;
